{{ silver_model_config('SEC_FILING_TEXT') }}

select
    accession_number,
    text_version,
    source_document_name,
    text_storage_path,
    text_sha256,
    char_count,
    extracted_at
from {{ source('edgartools_silver_landing', 'SEC_FILING_TEXT') }}
qualify row_number() over (
    partition by accession_number, text_version
    order by parse_sequence desc
) = 1
  and {{ silver_not_retired('sec_filing_text', "concat_ws('|', accession_number, text_version)") }}
